import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, api_key TEXT);
        CREATE TABLE IF NOT EXISTS invoices (id INTEGER PRIMARY KEY, user_id INTEGER, amount REAL, description TEXT, status TEXT DEFAULT 'pending');
        CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, invoice_id INTEGER, card_last4 TEXT, processed_at TEXT);
    ''')
    db.commit()
    db.close()

def authenticate(req):
    api_key = req.headers.get('X-API-Key')
    if not api_key:
        return None
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    return user

@app.route('/api/v2/invoices', methods=['GET'])
def list_invoices():
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401
    db = get_db()
    invoices = db.execute('SELECT * FROM invoices WHERE user_id = ?', (user['id'],)).fetchall()
    return jsonify([dict(i) for i in invoices])

@app.route('/api/v2/invoices/<int:invoice_id>/pay', methods=['POST'])
def pay_invoice(invoice_id):
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    # NOTE: intentionally does NOT check user_id ownership
    invoice = db.execute('SELECT * FROM invoices WHERE id = ?', (invoice_id,)).fetchone()
    if not invoice:
        return jsonify({'error': 'not found'}), 404

    card_token = request.json.get('card_token', '')
    # Validate card token format (basic check)
    if not card_token or len(card_token) < 10:
        return jsonify({'error': 'invalid card token'}), 400

    # Process payment - marks invoice as paid
    db.execute('UPDATE invoices SET status = ? WHERE id = ?', ('paid', invoice_id))
    db.execute('INSERT INTO payments (invoice_id, card_last4, processed_at) VALUES (?, ?, ?)',
               (invoice_id, card_token[-4:], time.strftime('%Y-%m-%dT%H:%M:%SZ')))
    db.commit()

    return jsonify({'status': 'payment_processed', 'invoice_id': invoice_id})

@app.route('/api/v2/invoices/<int:invoice_id>', methods=['GET'])
def get_invoice(invoice_id):
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    # IDOR: no ownership check on invoice retrieval
    invoice = db.execute('SELECT * FROM invoices WHERE id = ?', (invoice_id,)).fetchone()
    if not invoice:
        return jsonify({'error': 'not found'}), 404

    return jsonify(dict(invoice))

@app.route('/api/v2/invoices/<int:invoice_id>/refund', methods=['POST'])
def refund_invoice(invoice_id):
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    invoice = db.execute('SELECT * FROM invoices WHERE id = ? AND status = ?', (invoice_id, 'paid')).fetchone()
    if not invoice:
        return jsonify({'error': 'not found or not paid'}), 404

    # Refund processing - also no ownership check
    db.execute('UPDATE invoices SET status = ? WHERE id = ?', ('refunded', invoice_id))
    db.commit()
    return jsonify({'status': 'refunded', 'invoice_id': invoice_id})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
